292	    /// The first root key two blocks of the body would both write, or `None`. Sections render as root keys (a TOON
293	    /// list or text section under its name, a KV section as its item keys), beside the keys michi writes itself:
294	    /// `budget`, its `sections` table, `provenance`, `truncated`, `totalCount`, `help`, `recovery`, and, for a block
295	    /// that failed validation, `error` and `message`. `failed[i]` says whether block `i` failed. The reserved names
296	    /// are claimed whether or not that block is present, so validity never depends on the caller's data. Provenance
297	    /// labels sit one level down and collide only with each other and the `fingerprint` line.
298	    fn root_collision(&self, failed: &[bool]) -> Option<String> {
299	        const RESERVED: [&str; 7] = ["budget", "sections", "provenance", "truncated", "totalCount", "help", "recovery"];
300	        let blocks = self.blocks();
301	        let mut seen: std::collections::HashSet<&str> = RESERVED.into_iter().collect();
302	        for (s, failed) in blocks.iter().zip(failed) {
303	            if *failed {
304	                for key in ["error", "message"] {
305	                    if !seen.insert(key) {
306	                        return Some(key.to_string());
307	                    }
308	                }
309	                continue;
310	            }
311	            let keys: Vec<&str> = match &s.body {
312	                SectionBody::Toon { .. } | SectionBody::Text(_) => vec![s.name.as_str()],
313	                SectionBody::Kv(items) => items.iter().map(|i| i.key.as_str()).collect(),
314	            };
315	            for key in keys {
316	                if !seen.insert(key) {
317	                    return Some(key.to_string());
318	                }
319	            }
320	        }
321	        let p = self.provenance.as_ref()?;
322	        let mut labels: std::collections::HashSet<&str> = std::collections::HashSet::new();
323	        if p.fingerprint.is_some() {
324	            labels.insert("fingerprint");
325	        }
326	        p.entries.iter().find(|e| !labels.insert(e.label.as_str())).map(|e| e.label.clone())
327	    }
328	
329	    /// The body: sections, `budget:`, `provenance:`.
330	    ///
331	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
332	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
333	    /// one table with a leading `section` column, after the last block.
334	    ///
335	    /// The flag is whether this response is an error: set by `as_error()` or by a block that failed validation.
336	    /// Every output surface reads its error flag from here so text, JSON and MCP never disagree.
337	    fn body(&self) -> (String, bool, Vec<Hint>) {
338	        let blocks = self.blocks();
339	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
340	        let mut failed = false;
341	        let mut flags: Vec<bool> = Vec::with_capacity(blocks.len());
342	        let mut extras: Vec<Hint> = Vec::new();
343	        for s in blocks.iter() {
344	            let (part, part_failed, extra) = self.section_part(s);
345	            failed |= part_failed;
346	            flags.push(part_failed);
347	            // One line per cut response is enough: every section's line says the same thing.
348	            if let Some(h) = extra {
349	                if !extras.contains(&h) {
350	                    extras.push(h);
351	                }
352	            }
353	            parts.push(part);
354	        }
355	        // Two blocks writing one root key would be invalid TOON. Like any other bad input the whole body becomes the
356	        // visible validation error, so the caller sees it instead of a document a decoder rejects.
357	        if let Some(key) = self.root_collision(&flags) {
358	            return (collision_body(&key), true, Vec::new());
359	        }
360	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
361	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
362	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
363	        for p in &parts {
364	            join_block(&mut out, &p.text);
365	            if cutters == 1 && !p.cuts.is_empty() {
366	                join_block(&mut out, &truncated_table(std::slice::from_ref(p)));
367	            }
368	            if let (1, Some(n)) = (totals, p.total) {
369	                join_block(&mut out, &format!("totalCount: {n}"));
370	            }
371	        }
372	        if cutters >= 2 {
373	            join_block(&mut out, &truncated_table(&parts));
374	        }
375	        if totals >= 2 {
376	            join_block(&mut out, &total_table(&parts));
377	        }
378	        if let Some(b) = &self.budget {
379	            join_block(&mut out, &crate::budget::render_budget_block(b, self.sections.len() >= 2));
380	        }
381	        if let Some(p) = &self.provenance {
382	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
383	        }
384	        (out, failed || self.is_error, extras)
385	    }
386	
387	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
388	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
389	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
390	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
391	        let hints = self.hints_with(extra);
392	        if !hints.is_empty() || !self.recovery.is_empty() {
393	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
394	        }
395	        crate::hints::append_hints(&mut body, &hints);
396	        crate::recovery::append_recovery(&mut body, &self.recovery);
397	        body
398	    }
399	
400	    /// Render the response in the requested format.
401	    #[must_use]
402	    pub fn render(&self, format: OutputFormat) -> String {
403	        match format {
404	            OutputFormat::Text => self.render_text(),
405	            OutputFormat::Json => self.render_json(),
406	        }
407	    }
408	
409	    fn render_text(&self) -> String {
410	        let (body, _, extra) = self.body();
411	        self.finish_text(body, &extra)
412	    }
413	
414	    /// Whether this response is an error: `as_error()` was called, or a section's TOON rows or KV items failed
415	    /// validation and its block is a `toon_validation_failed` or `kv_validation_failed` error block. Validates
416	    /// without rendering.
417	    #[must_use]
418	    pub fn is_error(&self) -> bool {
419	        if self.is_error {
420	            return true;
421	        }
422	        let failed = self.failed_flags();
423	        failed.contains(&true) || self.root_collision(&failed).is_some()
424	    }
425	
426	    /// Render just the `help[N]:` block for `self.hints`.
427	    #[must_use]
428	    pub fn render_hints_only(&self) -> String {
429	        crate::hints::render_hints(&self.hints)
430	    }
431	
432	    /// Render for the given audience.
433	    #[must_use]
434	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
435	        match audience {
436	            crate::audience::Audience::Assistant => self.render_text(),
437	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
438	        }
439	    }
440	
441	    /// Whether `.human_content()` was set on this builder.
442	    #[must_use]
443	    pub fn has_human_content(&self) -> bool {
444	        self.human_content.is_some()
445	    }
446	
447	    /// Build the MCP `CallToolResult` for this response.
448	    #[must_use]
449	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
450	        let (body, is_error, extra) = self.body();
451	        let structured_content = self.json_from_body(&body, is_error, &extra);
452	        let mut content = vec![crate::mcp::ContentBlock {
453	            text: self.finish_text(body, &extra),
454	            audience: vec![crate::audience::Audience::Assistant],
455	        }];
456	        if let Some(human) = &self.human_content {
457	            content.push(crate::mcp::ContentBlock {
458	                text: human.clone(),
459	                audience: vec![crate::audience::Audience::User],
460	            });
461	        }
462	        crate::mcp::CallToolResult { content, is_error, structured_content }
463	    }
464	
465	    fn render_json(&self) -> String {
466	        let (body, is_error, extra) = self.body();
467	        self.json_from_body(&body, is_error, &extra)
468	    }
469	
470	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
471	        let hints = self.hints_with(extra);
472	        let capacity =
473	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
474	        let mut out = String::with_capacity(capacity + body.len() + 128);
475	        out.push_str("{\"body\":");
476	        json_string(&mut out, body);
477	        if !self.sections.is_empty() {
478	            out.push_str(",\"sections\":[");
479	            for (i, s) in self.sections.iter().enumerate() {
480	                if i > 0 {
481	                    out.push(',');
482	                }
483	                push_section_json(&mut out, s);
484	            }
485	            out.push(']');
486	        }
487	        if let Some(b) = &self.budget {
488	            out.push_str(",\"budget\":");
489	            out.push_str(&crate::budget::budget_json(b));
490	        }
491	        if let Some(p) = &self.provenance {
492	            out.push_str(",\"provenance\":");
493	            out.push_str(&crate::provenance::provenance_json(p));
494	        }
495	        out.push_str(",\"hints\":[");
496	        for (i, h) in hints.iter().enumerate() {
497	            if i > 0 {
498	                out.push(',');
499	            }
500	            json_string(&mut out, h.as_str());
501	        }
502	        out.push_str("],\"recovery\":[");
503	        for (i, r) in self.recovery.iter().enumerate() {
504	            if i > 0 {
505	                out.push(',');
506	            }
507	            out.push_str("{\"tool\":");
508	            json_string(&mut out, &r.tool);
509	            out.push_str(",\"params\":");
510	            crate::recovery::push_params_json(&mut out, &r.params);
511	            if let Some(reason) = &r.reason {
512	                out.push_str(",\"reason\":");
513	                json_string(&mut out, reason);
514	            }
515	            out.push('}');
516	        }
517	        out.push_str("],\"isError\":");
518	        out.push_str(if is_error { "true" } else { "false" });
519	        out.push('}');
520	        out
521	    }
522	}
523	
524	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
525	fn validation_error_body(code: &str, message: &str) -> String {
526	    let message = crate::toon::escape_value(message);
527	    let mut out = String::with_capacity(17 + code.len() + message.len());
528	    out.push_str("error: ");
529	    out.push_str(code);
530	    out.push_str("\nmessage: ");
531	    out.push_str(&message);
532	    out
533	}
534	
535	/// The body for two blocks that would write the same root key.
536	fn collision_body(key: &str) -> String {
537	    validation_error_body(
538	        "toon_validation_failed",
539	        &format!("duplicate root key '{key}': give every section and KV key a distinct name"),
540	    )
541	}
542	
543	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
544	struct Part<'a> {
545	    /// The block's name, the `section` column when several blocks share a root key.
546	    name: &'a str,
547	    /// The block's text without its `truncated` block or `totalCount` line.
548	    text: String,
549	    /// Cut cells as `(row, field name, chars removed)`.
550	    cuts: Vec<(usize, String, usize)>,
551	    /// The `totalCount` this block reports, when it reports one.
552	    total: Option<usize>,
553	}
554	
555	impl<'a> Part<'a> {
556	    /// A block that failed validation: the error body replaces its content and it reports no count.
557	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
558	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
559	    }
560	}

