300	    /// The process exit code to use when this error is fatal. Always `1`.
301	    #[must_use]
302	    pub fn exit_code(&self) -> i32 {
303	        1
304	    }
305	
306	    /// Render as a TOON 4.4 root object, with no trailing newline: `error: <code label>`, `message: …` (quoted per
307	    /// §7.2), the inline `causes[N]: …` array when there are causes, `exit_code: 1`, then the inline `help[N]: …`
308	    /// array and the `recovery[1]{tool,params,reason}:` table when present.
309	    #[must_use]
310	    pub fn render(&self) -> String {
311	        let causes_est: usize = self.causes.iter().map(|c| c.len() + 3).sum();
312	        let mut out = String::with_capacity(96 + self.message.len() + causes_est + self.hints.len() * 50);
313	        push_error_fields(&mut out, self.code.label(), &self.message, &self.causes);
314	        crate::hints::append_hints(&mut out, &self.hints);
315	        if let Some(r) = &self.recovery {
316	            crate::recovery::append_recovery(&mut out, std::slice::from_ref(r));
317	        }
318	        out
319	    }
