322	    ///
323	    /// The message is encoded as GitHub workflow command data: `%` becomes `%25` first, then CR and LF become `%0D`
324	    /// and `%0A`, so the annotation stays on one line and a literal `%0A` in the message cannot decode to a line
325	    /// break. The `title` property is encoded the same way plus `:` → `%3A` and `,` → `%2C`.
326	    #[must_use]
327	    pub fn render_github_annotation(&self) -> String {
