351	        out.push_str("{\"isError\":true,\"error\":");
352	        crate::kv::json_escape_str(&mut out, self.code.label());
353	        out.push_str(",\"message\":");
354	        crate::kv::json_escape_str(&mut out, &self.message);
355	        out.push_str(",\"causes\":[");
356	        for (i, c) in self.causes.iter().enumerate() {
357	            if i > 0 {
358	                out.push(',');
359	            }
360	            crate::kv::json_escape_str(&mut out, c);
361	        }
362	        out.push_str("],\"retryable\":");
363	        out.push_str(if self.retryable { "true" } else { "false" });
364	        out.push_str(",\"hints\":[");
365	        for (i, h) in self.hints.iter().enumerate() {
366	            if i > 0 {
367	                out.push(',');
368	            }
