487	    let mut out = String::with_capacity(s.len() + 8);
488	    for ch in s.chars() {
489	        match ch {
490	            '%' => out.push_str("%25"),
491	            '\r' => out.push_str("%0D"),
492	            '\n' => out.push_str("%0A"),
