556	    #[error("Invalid input: {0}")]
557	    InvalidInput(String),
558	
559	    /// A required resource was not found.
560	    #[error("Not found: {0}")]
561	    NotFound(String),
562	
563	    /// A classified domain error with hints, recovery, and retry metadata.
564	    #[error("{}: {}", .0.code.label(), .0.message)]
565	    Domain(#[from] DomainError),
