570	    /// error; `InvalidInput(m)` and `NotFound(m)` render `error: invalid_input` / `error: not_found`, `message: m`
571	    /// (quoted per §7.2) and `exit_code: 1`, with no trailing newline.
572	    #[must_use]
573	    pub fn render(&self) -> String {
574	        let (code, message) = match self {
575	            Self::Domain(d) => return d.render(),
576	            Self::InvalidInput(m) => (ErrorCode::InvalidInput.label(), m),
577	            Self::NotFound(m) => (ErrorCode::NotFound.label(), m),
578	        };
579	        let mut out = String::with_capacity(48 + message.len());
580	        push_error_fields(&mut out, code, message, &[]);
581	        out
582	    }
583	
584	    /// The process exit code to use when this error is fatal.
585	    #[must_use]
586	    pub fn exit_code(&self) -> i32 {
587	        1
588	    }
