590	    /// Classify this error for routing decisions.
591	    #[must_use]
592	    pub fn class(&self) -> ErrorClass {
593	        match self {
594	            Self::Domain(d) if d.retryable => ErrorClass::Transient,
595	            Self::Domain(d) => d.code.default_class(),
596	            Self::InvalidInput(_) | Self::NotFound(_) => ErrorClass::User,
