use michi_core::toon::Value;
use michi_core::*;
fn main() {
    // 1. DomainError invariant via public field
    let mut e = DomainError::new(ErrorCode::Timeout, "t");
    println!("1a new(Timeout) hints={:?} retryable={}", e.hints, e.retryable);
    e.retryable = true; // public field bypasses sync
    println!("1b after field retryable=true hints={:?}", e.hints);
    let mut e2 = DomainError::new(ErrorCode::RateLimited, "r");
    e2.code = ErrorCode::Timeout;
    println!("1c code changed to Timeout via field: retryable={} hints={:?}", e2.retryable, e2.hints);
    println!("1d render:\n{}", e.render());

    // 2. Section returned_count public field vs count()
    let mut s = Section::toon("a", vec!["x".into()], vec![vec![Value::Int(1)]]);
    s.returned_count = 50;
    println!("2 returned_count field=50, count()={}", s.count());
    let s2 = Section::toon("b", vec!["x".into()], vec![vec![Value::Int(1)]]).truncated(true);
    println!("2b truncated(true) with no total:\n{}", AgentResponse::new("t").section(s2.clone()).render(OutputFormat::Text));
    println!("2c json:\n{}", AgentResponse::new("t").section(s2).render(OutputFormat::Json));

    // 3. Budget roll-up disagreeing with sections; duplicated totals
    let r = AgentResponse::new("t")
        .section(Section::toon("a", vec!["x".into()], vec![vec![Value::Int(1)]]).total_count(Some(10)).truncated(true))
        .section(Section::toon("b", vec!["x".into()], vec![vec![Value::Int(2)]]).total_count(Some(5)))
        .budget(BudgetSummary::new().truncated(false).section(SectionCost::new("ghost", 99).total(1)));
    println!("3 text:\n{}\n3 json:\n{}", r.render(OutputFormat::Text), r.render(OutputFormat::Json));

    // 4. Pipeline id never rendered
    let p = pipeline::Pipeline::new("RUN-ID-123", vec![]);
    println!("4 pipeline render: {}", p.render());
    let p = pipeline::Pipeline::new(
        "RUN-ID-123",
        vec![pipeline::PipelineStep::new("s", "n", pipeline::StepStatus::Completed)],
    );
    println!("4b: {}", p.render());

    // 5. PartialSuccess duplicate index across categories
    let ps = PartialSuccess::new(
        vec![OpRef::new(0, "a")],
        vec![FailedOp::new(0, "a", "boom")],
        vec![OpRef::new(0, "b")],
    );
    println!("5 render:\n{}\nexit={}", ps.render(), ps.exit_code());

    // 6. Error vs DomainError
    let err = Error::InvalidInput("x".into());
    println!("6 Error::render: {} class={:?}", err.render(), err.class());

    // 7. render_hints_only skips truncation line
    let r = AgentResponse::new("t")
        .hint("h1")
        .truncation_hint("pass full=true")
        .section(Section::toon("a", vec!["x".into()], vec![vec![Value::from("x".repeat(500))]]));
    println!("7 full:\n{}\n7 hints_only: {}", r.render(OutputFormat::Text), r.render_hints_only());

    // 8. AgentResponse error vs DomainError structured content
    let r = AgentResponse::new("t").as_error().hint("x");
    println!("8 as_error structured: {}", r.to_call_tool_result().structured_content);
    println!(
        "8b domain structured: {}",
        DomainError::new(ErrorCode::NotFound, "m").to_call_tool_result().structured_content
    );
}

